<script setup lang="ts">
import { nextTick, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { state, createProject, createWorkflow } from '../store/workbench'
const router=useRouter(), projectDialog=ref<HTMLDialogElement>(), workflowDialog=ref<HTMLDialogElement>()
const project=reactive({name:'',description:'',actor:''}), workflow=reactive({title:'订单取消参考验证',goal:'逐步审阅需求、架构和实现，并核对真实参考测试证据。',actor:''})
const projectError=ref(''), workflowError=ref('')
watch(()=>state.showProject,async value=>{ await nextTick(); if(value) { project.actor=state.actor; projectError.value=''; projectDialog.value?.showModal() } else projectDialog.value?.close() })
watch(()=>state.showWorkflow,async value=>{ await nextTick(); if(value) { workflow.actor=state.actor; workflowError.value=''; workflowDialog.value?.showModal() } else workflowDialog.value?.close() })
function closeProject(event?:Event) { if(state.busy){event?.preventDefault();return} state.showProject=false }
function closeWorkflow(event?:Event) { if(state.busy){event?.preventDefault();return} state.showWorkflow=false }
async function submitProject() { if(state.busy)return; projectError.value=''; try { await createProject(project.name.trim(),project.description.trim(),project.actor.trim()); project.name='';project.description=''; await router.push('/projects') } catch(error){projectError.value=(error as Error).message} }
async function submitWorkflow() { if(state.busy)return; workflowError.value=''; try { const created=await createWorkflow(workflow.title.trim(),workflow.goal.trim(),workflow.actor.trim()); await router.push(`/workflows/${created.id}/overview`) } catch(error){workflowError.value=(error as Error).message} }
</script>
<template><dialog ref="projectDialog" class="form-dialog" @cancel="closeProject"><form @submit.prevent="submitProject"><div class="dialog-heading"><div><p class="eyebrow">创建项目</p><h2>创建验证项目</h2></div><button class="icon-button" type="button" :disabled="state.busy" aria-label="关闭" @click="closeProject()">×</button></div><p class="dialog-description">为本地验证建立清晰的知识边界。不会连接或修改业务仓库。</p><label class="field">项目名称<input v-model="project.name" required maxlength="200" placeholder="例如：工程协作验证" :disabled="state.busy"></label><label class="field">项目说明<textarea v-model="project.description" rows="3" maxlength="4000" placeholder="记录本次验证的目的（可选）" :disabled="state.busy"></textarea></label><label class="field">操作署名<input v-model="project.actor" required maxlength="100" autocomplete="name" placeholder="请输入你的姓名或本地署名" :disabled="state.busy"><small>用于记录谁创建了项目，不代表已完成身份认证。</small></label><p v-if="projectError" class="form-error" role="alert">{{ projectError }}</p><div class="dialog-footer"><button class="button secondary" type="button" :disabled="state.busy" @click="closeProject()">取消</button><button class="button primary" type="submit" :disabled="state.busy || !project.name.trim() || !project.actor.trim()">{{ state.busy ? '创建中…' : '创建项目' }}</button></div></form></dialog><dialog ref="workflowDialog" class="form-dialog" @cancel="closeWorkflow"><form @submit.prevent="submitWorkflow"><div class="dialog-heading"><div><p class="eyebrow">创建验证流程</p><h2>新建验证流程</h2></div><button class="icon-button" type="button" :disabled="state.busy" aria-label="关闭" @click="closeWorkflow()">×</button></div><div class="scenario-card"><span>参考场景</span><strong>订单取消 · 四阶段完整验证</strong><p>需求分析 → 架构设计 → 代码实现 → 测试验证</p></div><label class="field">流程名称<input v-model="workflow.title" required maxlength="200" :disabled="state.busy"></label><label class="field">验证目标<textarea v-model="workflow.goal" required rows="3" maxlength="4000" :disabled="state.busy"></textarea><small>目标记录本次验证意图，当前业务规则仍来自固定参考场景。</small></label><label class="field">操作署名<input v-model="workflow.actor" required maxlength="100" autocomplete="name" placeholder="请输入你的姓名或本地署名" :disabled="state.busy"></label><p v-if="workflowError" class="form-error" role="alert">{{ workflowError }}</p><div class="dialog-footer"><button class="button secondary" type="button" :disabled="state.busy" @click="closeWorkflow()">取消</button><button class="button primary" type="submit" :disabled="state.busy || !workflow.title.trim() || !workflow.goal.trim() || !workflow.actor.trim()">{{ state.busy ? '创建中…' : '创建草稿流程' }}</button></div></form></dialog></template>
